module data_collection (\n  input wire clk,\n  input wire rst_n,\n  input wire start,\n  input wire [63:0] x0,\n  input wire [63:0] y0,\n  input wire [63:0] ax,\n  input wire [63:0] ay,\n  input wire [63:0] bx,\n  input wire [63:0] by,\n  input wire [63:0] xs,\n  input wire [63:0] ys,\n  input wire [63:0] t,\n  output reg [63:0] result,\n  output reg done\n);\n  parameter MAX_NODES = 100;\n  localparam [2:0] IDLE = 3'd0;\n  localparam [2:0] GENERATE = 3'd1;\n  localparam [2:0] COMPUTE_DIST = 3'd2;\n  localparam [2:0] DOUBLE_LOOP = 3'd3;\n  localparam [2:0] DONE_STATE = 3'd4;\n  \n  reg [2:0] state;\n  reg [6:0] node_idx;\n  reg [6:0] i;\n  reg [6:0] j;\n  reg [63:0] max_count;\n  reg [63:0] x [0:MAX_NODES-1];\n  reg [63:0] y [0:MAX_NODES-1];\n  reg [63:0] dist_prefix [0:MAX_NODES-1];\n  \n  integer k;\n  \n  // Combinational calculations\n  wire [63:0] abs_x_i = (xs >= x[i]) ? (xs - x[i]) : (x[i] - xs);\n  wire [63:0] abs_y_i = (ys >= y[i]) ? (ys - y[i]) : (y[i] - ys);\n  wire [63:0] dist_i = abs_x_i + abs_y_i;\n  wire [63:0] abs_x_j = (xs >= x[j]) ? (xs - x[j]) : (x[j] - xs);\n  wire [63:0] abs_y_j = (ys >= y[j]) ? (ys - y[j]) : (y[j] - ys);\n  wire [63:0] dist_j = abs_x_j + abs_y_j;\n  wire [63:0] travel = dist_prefix[j] - dist_prefix[i];\n  wire [63:0] total1 = dist_i + travel;\n  wire [63:0] total2 = dist_j + travel;\n  wire condition = (total1 <= t) || (total2 <= t);\n  wire [63:0] count = {57'd0, j} - {57'd0, i} + 64'd1;\n  \n  always @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n      state <= IDLE;\n      done <= 1'b0;\n      result <= 64'd0;\n      node_idx <= 7'd0;\n      i <= 7'd0;\n      j <= 7'd0;\n      max_count <= 64'd0;\n      for (k = 0; k < MAX_NODES; k = k + 1) begin\n        x[k] <= 64'd0;\n        y[k] <= 64'd0;\n        dist_prefix[k] <= 64'd0;\n      end\n    end else begin\n      case (state)\n        IDLE: begin\n          done <= 1'b0;\n          if (start) begin\n            x[0] <= x0;\n            y[0] <= y0;\n            dist_prefix[0] <= 64'd0;\n            node_idx <= 7'd1;\n            state <= GENERATE;\n          end\n        end\n        \n        GENERATE: begin\n          if (node_idx < MAX_NODES) begin\n            x[node_idx] <= ax * x[node_idx-7'd1] + bx;\n            y[node_idx] <= ay * y[node_idx-7'd1] + by;\n            state <= COMPUTE_DIST;\n          end else begin\n            state <= DOUBLE_LOOP;\n            i <= 7'd0;\n            j <= 7'd0;\n            max_count <= 64'd0;\n          end\n        end\n        \n        COMPUTE_DIST: begin\n          dist_prefix[node_idx] <= dist_prefix[node_idx-7'd1] + \n            ((x[node_idx] >= x[node_idx-7'd1])\n              ? (x[node_idx] - x[node_idx-7'd1])\n              : (x[node_idx-7'd1] - x[node_idx])) +\n            ((y[node_idx] >= y[node_idx-7'd1])\n              ? (y[node_idx] - y[node_idx-7'd1])\n              : (y[node_idx-7'd1] - y[node_idx]));\n          node_idx <= node_idx + 7'd1;\n          state <= GENERATE;\n        end\n        \n        DOUBLE_LOOP: begin\n          if (condition) begin\n            if (count > max_count) begin\n              max_count <= count;\n            end\n          end\n          \n          if (j < (MAX_NODES - 7'd1)) begin\n            j <= j + 7'd1;\n          end else if (i < (MAX_NODES - 7'd1)) begin\n            i <= i + 7'd1;\n            j <= i + 7'd1;\n          end else begin\n            state <= DONE_STATE;\n          end\n        end\n        \n        DONE_STATE: begin\n          result <= max_count;\n          done <= 1'b1;\n          state <= IDLE;\n        end\n        \n        default: begin\n          state <= IDLE;\n        end\n      endcase\n    end\n  end\nendmodule